(4015795, 574142, 25355, '<td valign="top">I guess that''s a hawk moth,and I know they''re difficult to capture. Well done. I think I would have cropped in a bit closer.</td>', 'I guess that''s a hawk moth,and I know they''re difficult to capture. Well done. I think I would have cropped in a bit closer.', '2007-08-20 22:09:52.000000', NULL, 1),
(4015801, 574065, 34659, '<td valign="top">Great shot.  Amazing clarity - even of the pilot.  Good color tones and great cloudy backdrop.  Were you in the plane next to them???  ;-)  Bumping up.</td>', 'Great shot.  Amazing clarity - even of the pilot.  Good color tones and great cloudy backdrop.  Were you in the plane next to them???  ;-)  Bumping up.', '2007-08-20 22:12:04.000000', NULL, 1),
(4015802, 573829, 34659, '<td valign="top">Beautiful capture - great reflection.  Swans are indeed magnificent creatures.  We used to raise them.  I still appreciate their inherent beauty.  Nice job.</td>', 'Beautiful capture - great reflection.  Swans are indeed magnificent creatures.  We used to raise them.  I still appreciate their inherent beauty.  Nice job.', '2007-08-20 22:12:09.000000', NULL, 1),
(4015807, 573748, 42254, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2007-08-20 22:12:47.000000', NULL, 1),
(4015809, 573556, 25355, '<td valign="top">...and shoot out that dust spot! ;-Þ<br/>Good use of negative space.</td>', '...and shoot out that dust spot! ;-ÞGood use of negative space.', '2007-08-20 22:13:07.000000', NULL, 1),
(4015810, 572647, 34659, '<td valign="top">Amazing detail and color.  Great bokeh too.  The whites are a little bright compared to the brightness of the butterfly herself, but that''s nitpicking.</td>', 'Amazing detail and color.  Great bokeh too.  The whites are a little bright compared to the brightness of the butterfly herself, but that''s nitpicking.', '2007-08-20 22:13:10.000000', NULL, 1),
(4015812, 573864, 34659, '<td valign="top">Very dramatic image.  Great use of B/W, light/shadow.</td>', 'Very dramatic image.  Great use of B/W, light/shadow.', '2007-08-20 22:13:30.000000', NULL, 1),
(4015814, 574313, 34659, '<td valign="top">Terrific POV.  The ground seems to be tilted just a little, but love the height of the crop.</td>', 'Terrific POV.  The ground seems to be tilted just a little, but love the height of the crop.', '2007-08-20 22:14:26.000000', NULL, 1),
(4015817, 573812, 25355, '<td valign="top">Too bad about the benches in the background, but good stopped motion picture.</td>', 'Too bad about the benches in the background, but good stopped motion picture.', '2007-08-20 22:15:04.000000', NULL, 1),
