(4015824, 573449, 34659, '<td valign="top">I wasn''t crazy about this shot at first - I thought that the flower parts interfered too much with the subject of the bee.  However, it has grown on me and I think the fact that it is in B/W was a good choice.  Nice detail.</td>', 'I wasn''t crazy about this shot at first - I thought that the flower parts interfered too much with the subject of the bee.  However, it has grown on me and I think the fact that it is in B/W was a good choice.  Nice detail.', '2007-08-20 22:16:39.000000', NULL, 1),
(4015825, 573089, 25355, '<td valign="top">Angels Anonymous? Nice thinking out of the paper box. ;-Þ</td>', 'Angels Anonymous? Nice thinking out of the paper box. ;-Þ', '2007-08-20 22:16:41.000000', NULL, 1),
(4015826, 570894, 42254, '<td valign="top">Interesting subtle wings!</td>', 'Interesting subtle wings!', '2007-08-20 22:16:48.000000', NULL, 1),
(4015829, 574328, 34659, '<td valign="top">Very dark &amp; dramatic shot.  Creative and emotionally appealing.</td>', 'Very dark & dramatic shot.  Creative and emotionally appealing.', '2007-08-20 22:17:14.000000', NULL, 1),
(4015831, 573089, 34659, '<td valign="top">Simple and effective.  Good use of light &amp; color.  Great shadow play.</td>', 'Simple and effective.  Good use of light & color.  Great shadow play.', '2007-08-20 22:17:43.000000', NULL, 1),
(4015833, 573218, 42254, '<td valign="top">Wow...unusual position, although I''d go for a little more highlight on the swan to constrast with the black water. Great shot, though.</td>', 'Wow...unusual position, although I''d go for a little more highlight on the swan to constrast with the black water. Great shot, though.', '2007-08-20 22:18:10.000000', NULL, 1),
