(4015841, 573905, 34659, '<td valign="top">There''s a lot more detail in this image after you stop to look.  I love swans and this is a good shot of one on the rise.  The B/W-duotone works well too.</td>', 'There''s a lot more detail in this image after you stop to look.  I love swans and this is a good shot of one on the rise.  The B/W-duotone works well too.', '2007-08-20 22:20:15.000000', NULL, 1),
(4015842, 574069, 25355, '<td valign="top">Wild guess - Denmark?</td>', 'Wild guess - Denmark?', '2007-08-20 22:21:19.000000', NULL, 1),
(4015843, 572645, 42254, '<td valign="top">Interesting shot...good study in contrast. Perhaps a little less light to show translucent wings instead of transparent...unless they really are that transparent.</td>', 'Interesting shot...good study in contrast. Perhaps a little less light to show translucent wings instead of transparent...unless they really are that transparent.', '2007-08-20 22:21:21.000000', NULL, 1),
