(4015856, 574183, 42254, '<td valign="top">Beautiful...colors, composition, sharpness.</td>', 'Beautiful...colors, composition, sharpness.', '2007-08-20 22:22:56.000000', NULL, 1),
(4015858, 573250, 80542, '<td valign="top">Nice silhouette.</td>', 'Nice silhouette.', '2007-08-20 22:23:22.000000', NULL, 1),
