(4016836, 573436, 20608, '<td valign="top">interesting. Im not sure what the line down the center is it kind of makes this look like it could be a picture that you have simply taken a photo of.. I hope not.. and Im gonna give you the benefit here and say you processed a photo like this and say I LIKE IT! good luck in the challenge</td>', 'interesting. Im not sure what the line down the center is it kind of makes this look like it could be a picture that you have simply taken a photo of.. I hope not.. and Im gonna give you the benefit here and say you processed a photo like this and say I LIKE IT! good luck in the challenge', '2007-08-21 08:13:28.000000', NULL, 1),
(4016845, 573787, 67258, '<td valign="top">I find myself in a quandry over this one - the challenge is wings, physical or figurative, and yet the wings seem to be completely incedental to the photograph.  The level of detail and colour reproduction in the birds head are incredible, with an almost seering clarity of focus.  However as a photograph (and quite seperate from the challenge, too) it doesn''t quite work for me - something to do with the fact that focus is deep enough to allow the tip of the beek through to the neck to be sharp, but then drops off incredibly rapidly.  I am curious to see what lens you are using.</td>', 'I find myself in a quandry over this one - the challenge is wings, physical or figurative, and yet the wings seem to be completely incedental to the photograph.  The level of detail and colour reproduction in the birds head are incredible, with an almost seering clarity of focus.  However as a photograph (and quite seperate from the challenge, too) it doesn''t quite work for me - something to do with the fact that focus is deep enough to allow the tip of the beek through to the neck to be sharp, but then drops off incredibly rapidly.  I am curious to see what lens you are using.', '2007-08-21 08:39:29.000000', NULL, 1),
(4016849, 573400, 67258, '<td valign="top">I wish you had chosen a shorter focal length as I would have liked to have seen a little more of the environment in which the heron (I believe) was placed.</td>', 'I wish you had chosen a shorter focal length as I would have liked to have seen a little more of the environment in which the heron (I believe) was placed.', '2007-08-21 08:43:45.000000', NULL, 1),
(4016850, 573517, 67258, '<td valign="top">The idea of the angel reaching out to touch that sky is rather appealing, although I am less convinced with the exposure on the statue.</td>', 'The idea of the angel reaching out to touch that sky is rather appealing, although I am less convinced with the exposure on the statue.', '2007-08-21 08:45:15.000000', NULL, 1),
(4016858, 574331, 67258, '<td valign="top">I take it this is an advertising slogan?  I suspect thatthis is one of those photos that very definitely needs to be placed in its cultural context to work properly.  The photo itself appears well and evenly lit, although the composition does seem a little awkward.</td>', 'I take it this is an advertising slogan?  I suspect thatthis is one of those photos that very definitely needs to be placed in its cultural context to work properly.  The photo itself appears well and evenly lit, although the composition does seem a little awkward.', '2007-08-21 08:47:46.000000', NULL, 1),
(4016890, 574060, 56828, '<td valign="top">I like the idea.  I would have liked it more if the wings were more in focus (stopping the action)</td>', 'I like the idea.  I would have liked it more if the wings were more in focus (stopping the action)', '2007-08-21 09:25:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4016891, 573510, 56828, '<td valign="top">Like how you captured the color and detail.  There is one grass blade that slightly distracts around the tail up through the back wing.   But stilla  great mcaro.</td>', 'Like how you captured the color and detail.  There is one grass blade that slightly distracts around the tail up through the back wing.   But stilla  great mcaro.', '2007-08-21 09:26:43.000000', NULL, 1),
(4016892, 571877, 56828, '<td valign="top">Great shot.  If you would have moved over slightly to the right to keep his other hand in the frame I think this would have been even better. You would have not only captured him figuratively, but you would have also had his arms (human wings) looking as if they are helping him float.</td>', 'Great shot.  If you would have moved over slightly to the right to keep his other hand in the frame I think this would have been even better. You would have not only captured him figuratively, but you would have also had his arms (human wings) looking as if they are helping him float.', '2007-08-21 09:28:12.000000', NULL, 1),
(4016893, 573705, 56828, '<td valign="top">I think the negative hurt the photo a little here.  It doesn''t give it a since of flying or being in air. You nearly took the whole wing aspect out of it as you took out the flying feel to it.</td>', 'I think the negative hurt the photo a little here.  It doesn''t give it a since of flying or being in air. You nearly took the whole wing aspect out of it as you took out the flying feel to it.', '2007-08-21 09:31:24.000000', NULL, 1),
(4017011, 574325, 82534, '<td valign="top">Very original idea.  Not a bird / bug!</td>', 'Very original idea.  Not a bird / bug!', '2007-08-21 10:46:44.000000', NULL, 1),
(4017013, 574309, 82534, '<td valign="top">To me, the bird should be in focus and the background blurred.  It appears the trees are the subject of this shot.</td>', 'To me, the bird should be in focus and the background blurred.  It appears the trees are the subject of this shot.', '2007-08-21 10:47:17.000000', NULL, 1),
(4017016, 573871, 82534, '<td valign="top">Interesting interpretation.  Nice capture -- especially making the groom stand out.</td>', 'Interesting interpretation.  Nice capture -- especially making the groom stand out.', '2007-08-21 10:47:53.000000', NULL, 1),
(4017019, 574332, 82534, '<td valign="top">That dragon fly sure has seen better days!</td>', 'That dragon fly sure has seen better days!', '2007-08-21 10:48:20.000000', NULL, 1),
(4017021, 572288, 82534, '<td valign="top">Awesome crop on this shot!</td>', 'Awesome crop on this shot!', '2007-08-21 10:48:47.000000', NULL, 1),
(4017023, 574019, 82534, '<td valign="top">Great detail on teh wings and birds.  Amazing shot!</td>', 'Great detail on teh wings and birds.  Amazing shot!', '2007-08-21 10:50:06.000000', NULL, 1),
(4017025, 572689, 82534, '<td valign="top">I really like the crop and the detail on the wings.  The fringing around the trees in the background is a bit distracting, but this is still a great image.</td>', 'I really like the crop and the detail on the wings.  The fringing around the trees in the background is a bit distracting, but this is still a great image.', '2007-08-21 10:50:47.000000', NULL, 1),
