(4017033, 573882, 82534, '<td valign="top">The short DOF really gives this a dramatic look.</td>', 'The short DOF really gives this a dramatic look.', '2007-08-21 10:52:50.000000', NULL, 1),
(4017041, 573436, 80311, '<td valign="top">Photo!?!</td>', 'Photo!?!', '2007-08-21 10:56:33.000000', NULL, 1),
(4017046, 573841, 80311, '<td valign="top">Good photo!</td>', 'Good photo!', '2007-08-21 10:58:49.000000', NULL, 1),
(4017142, 573689, 64446, '<td valign="top">Interesting composition having a human there too. I also like the skies and the perspective with other things happening farther, with the water and houses in the background. Having these leveled (roof line''s tilted) would improve this image, imho.</td>', 'Interesting composition having a human there too. I also like the skies and the perspective with other things happening farther, with the water and houses in the background. Having these leveled (roof line''s tilted) would improve this image, imho.', '2007-08-21 11:52:22.000000', NULL, 1),
(4017145, 572805, 69368, '<td valign="top">too much grain here and the bird is out of focus</td>', 'too much grain here and the bird is out of focus', '2007-08-21 11:53:43.000000', NULL, 1),
(4017149, 574332, 64446, '<td valign="top">It never ceases to amaze me how they can survive in with this, or what made them get to this condition. Nice capture and good focus.</td>', 'It never ceases to amaze me how they can survive in with this, or what made them get to this condition. Nice capture and good focus.', '2007-08-21 11:56:12.000000', NULL, 1),
(4017158, 572723, 64446, '<td valign="top">I suppose this is a difficult shot to get, considering the light conditions these creatures live in. They are really scary, and there are lots of details here... Well done!</td>', 'I suppose this is a difficult shot to get, considering the light conditions these creatures live in. They are really scary, and there are lots of details here... Well done!', '2007-08-21 12:00:56.000000', NULL, 1),
(4017171, 573872, 64446, '<td valign="top">Lots of details, as we can see the scars on its wings. Well saturated (maybe a little too much?). The green bg is too brigh, it distracts and steals the attention from the subject. Nevertheless, an interesting and classic composition.</td>', 'Lots of details, as we can see the scars on its wings. Well saturated (maybe a little too much?). The green bg is too brigh, it distracts and steals the attention from the subject. Nevertheless, an interesting and classic composition.', '2007-08-21 12:14:47.000000', NULL, 1),
(4017236, 574243, 70181, '<td valign="top">Great timing and excellent job of stopping the motion of the wings.</td>', 'Great timing and excellent job of stopping the motion of the wings.', '2007-08-21 13:16:15.000000', NULL, 1),
(4017237, 573829, 70181, '<td valign="top">Nice dreamy look and great reflection.</td>', 'Nice dreamy look and great reflection.', '2007-08-21 13:16:34.000000', NULL, 1),
