(4017247, 573594, 70181, '<td valign="top">I usually don''t care for photos of statues, but this one is nice.  Good lighting, contrast, sharpness.  And the dramatic sky is a nice background.</td>', 'I usually don''t care for photos of statues, but this one is nice.  Good lighting, contrast, sharpness.  And the dramatic sky is a nice background.', '2007-08-21 13:20:26.000000', NULL, 1),
(4017249, 574318, 70181, '<td valign="top">Very interesting.  Great composition.</td>', 'Very interesting.  Great composition.', '2007-08-21 13:21:01.000000', NULL, 1),
(4017250, 573996, 70181, '<td valign="top">One of my favorites of the challenge.  Fantastic closeup with excellent sharpness.  Do you always sprinkle your models with powdered parmesan cheese?  :)</td>', 'One of my favorites of the challenge.  Fantastic closeup with excellent sharpness.  Do you always sprinkle your models with powdered parmesan cheese?  :)', '2007-08-21 13:22:40.000000', NULL, 1),
