(4019608, 574165, 44628, '<td valign="top">Interesting!</td>', 'Interesting!', '2007-08-22 03:28:53.000000', NULL, 1),
(4019617, 574041, 44628, '<td valign="top">Try a slower shutter next time and it won''t look as though the helicopter is suspended by a wire. Great aviation photos always have the props/rotors blurred and your''s are, but they could be blurred more, especially the tail rotor. It spins very fast.</td>', 'Try a slower shutter next time and it won''t look as though the helicopter is suspended by a wire. Great aviation photos always have the props/rotors blurred and your''s are, but they could be blurred more, especially the tail rotor. It spins very fast.', '2007-08-22 03:32:20.000000', NULL, 1),
