INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4024109, 574234, 33542, '<td valign="top">I think this would have been better if the girl had more light on her and her hair was out of her face a bit. Also, maybe a simpler outfit for her.</td>', 'I think this would have been better if the girl had more light on her and her hair was out of her face a bit. Also, maybe a simpler outfit for her.', '2007-08-23 13:47:11.000000', NULL, 1),
(4024119, 573218, 33542, '<td valign="top">Wow, this is crazy! Is the swan really doing that with its own wing? Is it a real swan?</td>', 'Wow, this is crazy! Is the swan really doing that with its own wing? Is it a real swan?', '2007-08-23 13:49:53.000000', NULL, 1),
(4024121, 574151, 25218, '<td valign="top">This is adorable - you''ve captured beautiful natural backlight (at least it looks natural - if it''s not, then you''ve done better than I think!) and the baby has the sweetest look. Nice and soft, and the slight angle gives it an extra, little something. Great job!</td>', 'This is adorable - you''ve captured beautiful natural backlight (at least it looks natural - if it''s not, then you''ve done better than I think!) and the baby has the sweetest look. Nice and soft, and the slight angle gives it an extra, little something. Great job!', '2007-08-23 13:50:36.000000', NULL, 1),
(4024123, 573512, 33542, '<td valign="top">Cute pose.</td>', 'Cute pose.', '2007-08-23 13:51:29.000000', NULL, 1),
(4024124, 574019, 25218, '<td valign="top">I really like the composition of this shot a lot, and you captured them in the perfect pose. Great job!</td>', 'I really like the composition of this shot a lot, and you captured them in the perfect pose. Great job!', '2007-08-23 13:51:36.000000', NULL, 1),
(4024127, 573987, 33542, '<td valign="top">I find the wing in the bottom of the frame to be really distracting.</td>', 'I find the wing in the bottom of the frame to be really distracting.', '2007-08-23 13:52:04.000000', NULL, 1),
(4024129, 573905, 25218, '<td valign="top">Beautiful soft tones in this duotone. Great job!</td>', 'Beautiful soft tones in this duotone. Great job!', '2007-08-23 13:52:31.000000', NULL, 1),
(4024132, 572723, 25218, '<td valign="top">Excellent shot of an unusual and fascinating subject! Great job!</td>', 'Excellent shot of an unusual and fascinating subject! Great job!', '2007-08-23 13:53:20.000000', NULL, 1),
(4024136, 572984, 33542, '<td valign="top">Very cute idea - not the best execution in my opinion - parts of the picture are very dark and her feet are blurred.</td>', 'Very cute idea - not the best execution in my opinion - parts of the picture are very dark and her feet are blurred.', '2007-08-23 13:54:23.000000', NULL, 1),
