(4026761, 573689, 72714, '<td valign="top">I like the way you have created depth in this photo by placing the swans in the foreground, the waterline with the male figure in the middle and the houses in the background. I feel that the horizon needs straigtening ever so slightly though.</td>', 'I like the way you have created depth in this photo by placing the swans in the foreground, the waterline with the male figure in the middle and the houses in the background. I feel that the horizon needs straigtening ever so slightly though.', '2007-08-24 17:53:35.000000', NULL, 1),
(4026765, 574235, 72714, '<td valign="top">Wow, this is really in your face! I love the ''silver, chrome'' feel to the photo. Converting to B&amp;W was a good choice. Well captured.</td>', 'Wow, this is really in your face! I love the ''silver, chrome'' feel to the photo. Converting to B&W was a good choice. Well captured.', '2007-08-24 17:54:58.000000', NULL, 1),
