(4026834, 572640, 44877, '<td valign="top">I absolutely love this photo - magical! I hope it does well despite not being dpc-esque. 10</td>', 'I absolutely love this photo - magical! I hope it does well despite not being dpc-esque. 10', '2007-08-24 18:36:12.000000', NULL, 1),
(4026843, 573512, 72714, '<td valign="top">Beautiful! I love the soft focus effect and the pose works really well. I do feel that the subject is a bit central though, especially as there is quite a bit of space around her.</td>', 'Beautiful! I love the soft focus effect and the pose works really well. I do feel that the subject is a bit central though, especially as there is quite a bit of space around her.', '2007-08-24 18:40:43.000000', NULL, 1),
